"use client";

import { useState } from "react";
import { PanelShell } from "../../../components/PanelShell";
import { turkishCities } from "../../../data/cities";
import { addDemoCampaign, addDemoEvent } from "../../../lib/demo-store";

const steps = ["Temel bilgiler", "Sanatçı", "Mekan", "Tarih", "Salon ve koltuk", "Bilet", "Kampanya", "Önizleme", "Yayın"];

export default function NewEventPage() {
  const [step, setStep] = useState(0); const [title, setTitle] = useState("Yeni Ankara Gecesi"); const [category, setCategory] = useState("Stand-up"); const [artist, setArtist] = useState("BULUŞ Sahne"); const [place, setPlace] = useState("Milyon Performance Hall"); const [basePrice, setBasePrice] = useState(600); const [capacity, setCapacity] = useState(1600); const [sessions, setSessions] = useState([["Ankara", "12.09.2026", "20:30"], ["İstanbul", "20.09.2026", "20:00"], ["İzmir", "30.09.2026", "20:30"]]); const [publishedSlug, setPublishedSlug] = useState(""); const [resultStatus,setResultStatus]=useState<"Yayında"|"Taslak"|"İncelemede">("Yayında"); const [publishMode,setPublishMode]=useState<"Yayında"|"Taslak"|"İncelemede">("Yayında"); const [ticketTypes,setTicketTypes]=useState(["VIP","A Kategori","B Kategori"]); const [campaigns,setCampaigns]=useState<string[]>([]);
  function publishEvent(status = publishMode) {
    const session = sessions[0] ?? ["Ankara", "12.09.2026", "20:30"];
    const [day = "12", monthNumber = "09", year = "2026"] = session[1].split(".");
    const month = ({"01":"OCA","02":"ŞUB","03":"MAR","04":"NİS","05":"MAY","06":"HAZ","07":"TEM","08":"AĞU","09":"EYL","10":"EKİ","11":"KAS","12":"ARA"} as Record<string,string>)[monthNumber] ?? "EYL";
    const art = category === "Konser" ? "art-concert" : category === "Tiyatro" ? "art-theatre" : "art-standup";
    const created = addDemoEvent({ title: title.trim() || "Adsız Etkinlik", artist: artist.trim() || "BULUŞ Sahne", category, day, month, isoDate: `${year}-${monthNumber}-${day}`, place: place.trim() || "Milyon Performance Hall", city: session[0], price: basePrice, score: 84, scoreLabel: "Yeni etkinlik", art, mark: category === "Konser" ? "SESİ\nYAKALA" : category === "Tiyatro" ? "PERDE\nAÇILIYOR" : "GECE\nSENİN", description: `${title} için organizatör panelinden oluşturulan test etkinliği.`, capacity, time: session[2], status });
    setResultStatus(status); setPublishedSlug(created.slug);
  }
  const action = <div className="wizard-head-actions"><button type="button" onClick={()=>publishEvent("Taslak")}>Taslağı kaydet</button><button type="button" onClick={()=>setStep(7)}>Önizle ↗</button></div>;
  return <PanelShell active="Etkinlikler" title="Yeni etkinlik oluştur" subtitle="Tek bir ana etkinlikten tüm turne tarihlerini yönet." action={action}>
    <section className="event-wizard"><aside>{steps.map((label,index) => <button className={index === step ? "active" : index < step ? "done" : ""} type="button" onClick={() => setStep(index)} key={label}><span>{index < step ? "✓" : index + 1}</span><p>{label}<small>{index === 3 ? `${sessions.length} seans` : index < step ? "Tamamlandı" : index === step ? "Şimdi düzenleniyor" : "Bekliyor"}</small></p></button>)}</aside><div className="wizard-content">{publishedSlug ? <div className="publish-success"><span>✓</span><small>DEMO ETKİNLİĞİ {resultStatus.toLocaleUpperCase("tr-TR")}</small><h2>Etkinliğin sisteme kaydedildi.</h2><p>{resultStatus === "Yayında" ? "Keşfet ekranında görünüyor; test satışı yaptığında bilet ve panel rakamları otomatik güncellenecek." : resultStatus === "İncelemede" ? "Admin moderasyon kuyruğuna gönderildi. Admin onayından sonra yayına alınabilir." : "Taslaklar listesine kaydedildi; dilediğinde yayına alabilirsin."}</p><div className="publish-links">{resultStatus === "Yayında" && <a href={`/demo-event/${publishedSlug}`}>Etkinliği aç →</a>}<a href="/organizer/events">Etkinliklere dön</a></div></div> : <><div className="wizard-step-label">ADIM {step + 1} / {steps.length}</div><h2>{steps[step]}</h2><p className="wizard-description">{step === 0 ? "Kullanıcıların göreceği ana etkinlik bilgilerini oluştur." : step === 3 ? "Turne tarihlerini tek tek ekle veya örnek CSV verisini yükle." : step === 4 ? "Salon kapasitesini ve koltuk düzenini oluştur." : step === 7 ? "Etkinliğin kullanıcı tarafında nasıl görüneceğini kontrol et." : step === 8 ? "Test etkinliğini yayınla veya onaya gönder." : "Bu adım için gerekli seçimleri tamamla."}</p>{step === 0 && <div className="wizard-form"><label>Etkinlik adı<input value={title} onChange={(event) => setTitle(event.target.value)} /></label><div><label>Kategori<select value={category} onChange={event => setCategory(event.target.value)}><option>Stand-up</option><option>Konser</option><option>Tiyatro</option><option>Sergi</option><option>Aile</option></select></label><label>Dil<select><option>Türkçe</option><option>İngilizce</option></select></label></div><label>Açıklama<textarea defaultValue="Organizatör panelinden oluşturulan yeni test etkinliği." /></label><div><label>Süre (dk)<input defaultValue="120" /></label><label>Yaş sınırı<select><option>18+</option><option>13+</option><option>Genel izleyici</option></select></label></div><label className="upload-box"><span>＋</span><strong>Kapak görseli seç</strong><small>Dosya seçilmezse kategori tasarımı kullanılır</small><input type="file" accept="image/*" /></label></div>}{step === 1 && <div className="entity-select"><label>Sanatçı veya ekip<input value={artist} onChange={event => setArtist(event.target.value)} placeholder="Sanatçı adı" /></label><article><div>{artist.slice(0,2).toUpperCase()}</div><p><strong>{artist || "Yeni sanatçı"} <span>✓</span></strong><small>Demo sanatçı profili</small></p><b>Seçildi ✓</b></article><button type="button" onClick={()=>{const value=prompt("Yeni sanatçı adı",artist);if(value)setArtist(value)}}>+ Yeni sanatçı profili oluştur</button></div>}{step === 2 && <div className="entity-select"><label>Mekan<input value={place} onChange={event => setPlace(event.target.value)} placeholder="Mekan adı" /></label><article><div>{place.slice(0,2).toUpperCase()}</div><p><strong>{place || "Yeni mekan"} <span>✓</span></strong><small>{sessions[0]?.[0] ?? "Ankara"} · {capacity.toLocaleString("tr-TR")} kapasite</small></p><b>Seçildi ✓</b></article><button type="button" onClick={()=>{const value=prompt("Yeni mekan adı",place);if(value)setPlace(value)}}>+ Yeni mekan oluştur</button></div>}{step === 3 && <div className="session-builder"><div className="bulk-actions"><button type="button" onClick={()=>setSessions([["Ankara","12.09.2026","20:30"],["İstanbul","20.09.2026","20:00"],["İzmir","30.09.2026","20:30"],["Bursa","04.10.2026","19:30"]])}>↑ Örnek CSV verisini yükle</button><button type="button" onClick={() => setSessions([...sessions,["Ankara","","20:00"]])}>+ Tarih ekle</button></div>{sessions.map((session,index) => <div className="session-line" key={index}><span>{index + 1}</span><select value={session[0]} onChange={event => setSessions(sessions.map((item,i) => i === index ? [event.target.value,item[1],item[2]] : item))}>{turkishCities.map(city=><option key={city}>{city}</option>)}</select><input value={session[1]} onChange={(event) => setSessions(sessions.map((item,i) => i === index ? [item[0],event.target.value,item[2]] : item))} placeholder="GG.AA.YYYY" /><input value={session[2]} onChange={(event) => setSessions(sessions.map((item,i) => i === index ? [item[0],item[1],event.target.value] : item))} /><button type="button" onClick={() => setSessions(sessions.filter((_,i) => i !== index))}>×</button></div>)}<div className="session-note">✓ {sessions.length} tarih tek bir “{title}” ana etkinliğine bağlanacak.</div></div>}{step === 4 && <div className="hall-editor"><div className="hall-toolbar"><button type="button" onClick={()=>setCapacity(capacity+8)}>+ Sıra</button><button type="button" onClick={()=>setCapacity(capacity+1)}>+ Koltuk</button><button type="button" onClick={()=>setCapacity(capacity+4)}>+ Masa</button><button type="button" onClick={()=>setCapacity(Math.max(1,capacity-8))}>− Alan küçült</button></div><div className="mini-stage">SAHNE</div>{["A","B","C","D"].map(row => <div className="mini-seat-row" key={row}><b>{row}</b>{Array.from({length:8},(_,i) => <span key={i}>{i+1}</span>)}</div>)}<div className="hall-counters"><span>Toplam kapasite <b>{capacity.toLocaleString("tr-TR")}</b></span><span>VIP <b>{Math.round(capacity * .125)}</b></span><span>Standart <b>{Math.round(capacity * .875)}</b></span></div></div>}{step === 5 && <div className="ticket-type-list"><div className="demo-ticket-settings"><label>Başlangıç fiyatı<input type="number" value={basePrice} onChange={event => setBasePrice(Number(event.target.value))} /><b>TL</b></label><label>Toplam kapasite<input type="number" value={capacity} onChange={event => setCapacity(Number(event.target.value))} /></label></div>{ticketTypes.map((name,index) => <article key={name}><span>{name}</span><label>Fiyat<input value={basePrice+(ticketTypes.length-index-1)*300} readOnly /><b>TL</b></label><label>Kapasite<input value={Math.round(capacity/ticketTypes.length)} readOnly /></label><button type="button" onClick={()=>ticketTypes.length>1&&setTicketTypes(ticketTypes.filter(item=>item!==name))}>Sil</button></article>)}<button type="button" onClick={()=>{const value=prompt("Kategori adı",`Kategori ${ticketTypes.length+1}`);if(value)setTicketTypes([...ticketTypes,value])}}>+ Bilet kategorisi ekle</button></div>}{step === 6 && <div className="campaign-choice">{[["%","Erken dönem","ERKEN20",20],["4×","Grup kampanyası","GRUP30",30],["⌁","Kupon kodu","BULUS100",100]].map(item=><article key={String(item[1])}><span>{item[0]}</span><h3>{item[1]}</h3><p>{item[2]} koduyla test indirimi.</p><button type="button" disabled={campaigns.includes(String(item[2]))} onClick={()=>{addDemoCampaign({name:String(item[1]),code:String(item[2]),kind:Number(item[3])===100?"Tutar":"Yüzde",value:Number(item[3]),usageLimit:100,active:true});setCampaigns([...campaigns,String(item[2])])}}>{campaigns.includes(String(item[2]))?"Eklendi ✓":"Ekle"}</button></article>)}</div>}{step === 7 && <div className="wizard-preview"><div className="mini-preview-art"><span>{category.toLocaleUpperCase("tr-TR")}</span><strong>{title.split(" ").slice(0,2).map(word => <i key={word}>{word}<br /></i>)}</strong></div><div><span>YAYIN ÖNCESİ ÖNİZLEME</span><h2>{title}</h2><p>{artist} · {sessions.length} şehir · {basePrice} TL'den</p><ul>{sessions.map((item,index) => <li key={`${item[0]}-${index}`}><b>{item[0]}</b><span>{item[1]} · {item[2]}</span></li>)}</ul></div></div>}{step === 8 && <div className="publish-options"><label><input type="radio" name="publish" checked={publishMode==="Taslak"} onChange={()=>setPublishMode("Taslak")} /><span>◷</span><p><strong>Taslak olarak sakla</strong><small>Daha sonra düzenlemeye devam et.</small></p></label><label><input type="radio" name="publish" checked={publishMode==="İncelemede"} onChange={()=>setPublishMode("İncelemede")} /><span>✓</span><p><strong>Admin onayına gönder</strong><small>Moderasyon kuyruğuna eklenir.</small></p></label><label><input type="radio" name="publish" checked={publishMode==="Yayında"} onChange={()=>setPublishMode("Yayında")} /><span>↗</span><p><strong>Demo olarak şimdi yayınla</strong><small>Keşfet ekranında hemen görüntülenir.</small></p></label></div>}<div className="wizard-footer"><button type="button" disabled={step === 0} onClick={() => setStep(step - 1)}>← Geri</button><span>Form bilgileri bu ekranda korunuyor ✓</span><button type="button" onClick={() => step === steps.length - 1 ? publishEvent() : setStep(step + 1)}>{step === steps.length - 1 ? publishMode === "Yayında" ? "Demo etkinliğini yayınla ✓" : publishMode === "Taslak" ? "Taslağı kaydet ✓" : "Onaya gönder ✓" : "Kaydet ve devam et →"}</button></div></>}</div></section>
  </PanelShell>;
}
